import {specimens} from './specimens.js';
export function specimenDialog(type,icon){const s=specimens[type],moving=!matchMedia('(prefers-reduced-motion: reduce)').matches;return {title:type==='cell'?'Một thế giới trong tế bào':type==='dna'?'Mật mã của sự sống':s.title,eyebrow:`THƯ VIỆN TƯƠNG TÁC / ${s.category}`,html:`<p class="dialog-lead">Kéo để xoay, chọn cấu trúc hoặc bật đèn để nhìn rõ hơn. Mỗi góc nhìn là một cách khám phá mới.</p><div class="modal-columns"><div><div class="model-viewer" id="model-canvas"><span class="viewer-tip">${icon('move')} KÉO ĐỂ XOAY · CUỘN ĐỂ PHÓNG TO</span></div><div class="viewer-tools"><button data-action="model-auto" aria-pressed="${moving}">${icon(moving?'pause':'play')} <span>${moving?'Tự xoay':'Đã dừng'}</span></button><div style="display:flex;gap:6px"><button data-action="zoom-in" aria-label="Phóng to">${icon('plus')}</button><button data-action="zoom-out" aria-label="Thu nhỏ">${icon('minus')}</button><button data-action="model-reset" aria-label="Đặt lại góc nhìn">${icon('rotate')}</button></div><button data-action="model-light" aria-pressed="false">${icon('sun')} <span>Đèn quan sát</span></button>${type!=='dna'?`<button data-action="model-shell" aria-pressed="true">${icon('layers')} <span>${type==='cell'?'Thành tế bào':'Lớp bao'}</span></button>`:''}</div><p class="model-disclaimer">Mô hình minh họa cắt lớp chọn lọc · Màu quy ước · Không theo tỉ lệ.</p><p class="model-keyboard">Tab vào mô hình, dùng phím mũi tên để xoay và + / − để phóng to, thu nhỏ.</p></div><div><div class="organelle-list">${Object.entries(s.parts).map(([id,p])=>`<button data-organelle="${id}" aria-pressed="false">${p.name}</button>`).join('')}</div><div class="organelle-detail" id="organelle-detail" aria-live="polite"></div><button class="dialog-link" data-action="lesson" data-id="${s.lesson}">Đọc bài liên quan ${icon('arrow-right')}</button><button class="dialog-link" data-action="new-note" data-title="Khám phá: ${s.title}">Ghi lại phát hiện ${icon('notebook')}</button><a class="model-source" href="${s.source}" target="_blank" rel="noopener">Nguồn tham khảo: OpenStax Biology 2e ↗</a></div></div>`}}
